import { z } from 'zod';
import type { FormFieldMeta } from '../forms/form-field-meta';

export const heroSchema = z.object({
  name: z
    .string()
    .min(1, 'Name is required')
    .meta({
      label: 'Name',
      control: 'text',
      placeholder: 'e.g. Silverwing',
      help: "The hero's public codename.",
    } satisfies FormFieldMeta),
  alias: z.string().meta({
    label: 'Alias',
    control: 'text',
    placeholder: 'e.g. Ada Voss',
    help: 'The civilian identity. Leave blank if unknown.',
  } satisfies FormFieldMeta),
  powerClass: z.enum(['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced']).meta({
    label: 'Power class',
    control: 'select',
    options: [
      { value: 'Aerial', label: 'Aerial' },
      { value: 'Energy', label: 'Energy' },
      { value: 'Psionic', label: 'Psionic' },
      { value: 'Tech', label: 'Tech' },
      { value: 'Mutant', label: 'Mutant' },
      { value: 'Cosmic', label: 'Cosmic' },
      { value: 'Enhanced', label: 'Enhanced' },
    ],
  } satisfies FormFieldMeta),
  power: z
    .number()
    .min(0, 'Power index must be at least 0')
    .max(100, 'Power index must not exceed 100')
    .meta({
      label: 'Power index',
      control: 'number',
      help: 'Scored from 0 to 100. Higher is stronger.',
    } satisfies FormFieldMeta),
  status: z.enum(['Active', 'Injured', 'Reserve', 'MIA']).meta({
    label: 'Status',
    control: 'select',
    options: [
      { value: 'Active', label: 'Active' },
      { value: 'Injured', label: 'Injured' },
      { value: 'Reserve', label: 'Reserve' },
      { value: 'MIA', label: 'MIA' },
    ],
  } satisfies FormFieldMeta),
  clearance: z.enum(['Tier 1', 'Tier 2', 'Tier 3', 'Tier 4', 'Tier 5']).meta({
    label: 'Clearance',
    control: 'select',
    options: [
      { value: 'Tier 1', label: 'Tier 1' },
      { value: 'Tier 2', label: 'Tier 2' },
      { value: 'Tier 3', label: 'Tier 3' },
      { value: 'Tier 4', label: 'Tier 4' },
      { value: 'Tier 5', label: 'Tier 5' },
    ],
  } satisfies FormFieldMeta),
  notes: z.string().meta({
    label: 'Notes',
    control: 'textarea',
    placeholder: 'Field notes and deployment constraints',
    help: 'Up to 500 characters.',
  } satisfies FormFieldMeta),
  active: z
    .boolean()
    .meta({ label: 'On active roster', control: 'checkbox' } satisfies FormFieldMeta),
});

export type HeroFormModel = z.infer<typeof heroSchema>;
