    <button hlmSidebarTrigger class="app-topbar__menu"></button>
    <nav aria-label="Breadcrumb" class="app-topbar__nav">
      <ol class="app-topbar__trail">
        @for (crumb of crumbs(); track crumb.label; let last = $last) {
          <li class="app-topbar__crumb">
            @if (crumb.link && !last) {
              <a hlmSmall [routerLink]="crumb.link">{{ crumb.label }}</a>
              <ng-icon name="lucideChevronRight" class="app-topbar__sep" aria-hidden="true" />
            } @else {
              <span hlmSmall aria-current="page">{{ crumb.label }}</span>
            }
          </li>
        }
      </ol>
    </nav>
  </div>

  <div class="app-topbar__actions">
    <input
      hlmInput
      type="search"
      class="app-topbar__search"
      aria-label="Search heroes and missions"
      placeholder="Search heroes and missions"
    />
    <button
      hlmBtn
      variant="ghost"
      size="icon"
      class="app-topbar__button"
      aria-label="Notifications"
      hlmTooltip="Notifications"
    >
      <ng-icon name="lucideBell" />
    </button>
    <button
      hlmBtn
      variant="ghost"
      size="icon"
      class="app-topbar__button"
      [attr.aria-label]="dark() ? 'Switch to light theme' : 'Switch to dark theme'"
      [hlmTooltip]="dark() ? 'Light theme' : 'Dark theme'"
      (click)="toggleTheme.emit()"
    >
      <ng-icon [name]="dark() ? 'lucideSun' : 'lucideMoon'" />
    </button>
    <hlm-avatar class="app-topbar__avatar" role="img" aria-label="Signed in as Ops Commander">
      <span hlmAvatarFallback>OC</span>
    </hlm-avatar>
  </div>
</header>
